import React, { useState, useRef, useEffect } from "react";

// PenRunner — Prototipo "Pagina evento pubblica" (portale, registro scuro)
// Regola del contesto per il pubblico: la pagina cambia natura con lo stadio
// dell'evento — vetrina → iscrizioni → programma → DIRETTA → albo d'oro.
// Classifiche per livello (BR-88) + generale di categoria "non ufficiale".
// Il selettore stadi in alto è uno strumento di collaudo del prototipo.

const HERO = "data:image/jpeg;base64,";

const C = {
  accent: "#15803D", accent500: "#16A34A",
  ink900: "#0B1120", panel: "#141C2E", panel2: "#1E293B",
  slate300: "#CBD5E1", slate400: "#94A3B8", slate500: "#64748B",
  white: "#FFFFFF", live: "#DC2626", gold: "#C8902F", warn: "#F59E0B",
};
const num = { fontVariantNumeric: "tabular-nums" };

const STADI = ["Annunciato", "Iscrizioni", "Draw", "In diretta", "Concluso"];

const CLASSI = [
  { nome: "Open · L1–L4", added: "1.500 €", iscritti: 14, pattern: 12 },
  { nome: "Non Pro · L1–L4", added: "800 €", iscritti: 9, pattern: 8 },
  { nome: "Rookie · L1 L2", added: null, iscritti: 12, pattern: 7 },
  { nome: "Green · L1", added: null, iscritti: 6, pattern: 4 },
];

const PatternChip = ({ n }) => (
  <button style={{ background: C.panel2, border: "none", borderRadius: 6, padding: "3px 9px", fontSize: 11, fontWeight: 700, color: C.slate300, cursor: "pointer", ...num }}>
    Pattern {n} ↗
  </button>
);

// classifica live Rookie: per livello + generale non ufficiale
const Sec = ({ title, children, extra, accent }) => (
  <section style={{ background: C.panel, borderRadius: 12, padding: "16px 18px", marginBottom: 14, borderLeft: accent ? `3px solid ${accent}` : "none" }}>
    <div style={{ display: "flex", alignItems: "baseline", marginBottom: 10 }}>
      <h2 style={{ fontSize: 12, margin: 0, color: C.slate400, textTransform: "uppercase", letterSpacing: 1 }}>{title}</h2>
      {extra && <span style={{ marginLeft: "auto" }}>{extra}</span>}
    </div>
    {children}
  </section>
);

const Row = ({ children }) => (
  <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "9px 0", borderTop: `1px solid ${C.panel2}` }}>{children}</div>
);

// la classifica si deriva dall'ordine: run corse, ordinate per score
const LIVELLI_CLASSIFICA = { "Rookie · L1 L2": ["L1", "L2", "GEN"], "Green · L1": null, "Youth 14-18": null };

function Classifica({ q = "" }) {
  const classi = Object.keys(ORDINI);
  const [classe, setClasse] = useState(classi.find((c) => ORDINI[c].stato === "corsa") || classi[0]);
  const [tab, setTab] = useState("L1");
  const query = q.trim().toLowerCase();
  const dati = ORDINI[classe];
  const livelli = LIVELLI_CLASSIFICA[classe];
  const corse = dati.righe.filter((x) => x.stato === "fatto");
  const righe = corse
    .filter((x) => !livelli || tab === "GEN" || (x.liv || []).includes(tab))
    .filter((x) => !query || (x.c + " " + x.r + " " + (x.sc || "")).toLowerCase().includes(query))
    .sort((a, b) => parseFloat(b.score.replace(",", ".")) - parseFloat(a.score.replace(",", ".")));
  const titolo = `${classe} — Classifica ${dati.stato === "conclusa" ? "finale" : "provvisoria"}`;
  return (
    <Sec title={titolo} extra={
      livelli && (
        <span style={{ display: "flex", gap: 4 }}>
          {livelli.map((t) => (
            <button key={t} onClick={() => setTab(t)} style={{
              border: "none", borderRadius: 6, padding: "4px 10px", fontSize: 11.5, fontWeight: 700, cursor: "pointer",
              background: tab === t ? C.accent : C.panel2, color: C.white,
            }}>{t === "GEN" ? "Generale" : t}</button>
          ))}
        </span>
      )
    }>
      <div style={{ display: "flex", gap: 4, marginBottom: 10, flexWrap: "wrap" }}>
        {classi.map((c) => (
          <button key={c} onClick={() => { setClasse(c); setTab("L1"); }} style={{
            border: "none", borderRadius: 99, padding: "6px 12px", fontSize: 12, fontWeight: 700, cursor: "pointer",
            background: classe === c ? C.white : C.panel2, color: classe === c ? C.ink900 : C.slate300,
          }}>{c}</button>
        ))}
      </div>
      {tab === "GEN" && livelli && (
        <div style={{ fontSize: 11, color: C.warn, marginBottom: 6 }}>Vista non ufficiale — i livelli premiano separatamente</div>
      )}
      {corse.length === 0 && (
        <div style={{ fontSize: 13, color: C.slate400, padding: "10px 0" }}>Nessuno score ancora: la classifica si riempie con le run.</div>
      )}
      {righe.map((x, i) => {
        const podio = ["#C8902F", "#94A3B8", "#B45309"];
        const multiGiudice = x.g && x.g.length > 1;
        return (
          <Row key={x.c}>
            <span style={{ width: 22, color: i < 3 && !x.pen ? podio[i] : C.slate500, fontWeight: 800, ...num }}>{x.pen ? "—" : i + 1}</span>
            <div style={{ minWidth: 0, flex: 1 }}>
              <div style={{ fontSize: 14, fontWeight: i === 0 && !x.pen ? 800 : 700 }}>{x.c}</div>
              <div style={{ fontSize: 11.5, color: C.slate400 }}>{x.r}{tab === "GEN" && x.liv ? ` · ${x.liv.join(" ")}` : ""}{x.pen ? ` · ${x.pen}` : ""}</div>
            </div>
            {multiGiudice && (
              <span style={{ display: "flex", gap: 10 }}>
                {x.g.map((s, k) => (
                  <span key={k} style={{ width: 38, textAlign: "right", fontSize: 12, color: x.pen ? C.slate500 : C.slate300, ...num }}>{s}</span>
                ))}
              </span>
            )}
            <strong style={{ marginLeft: multiGiudice ? 0 : "auto", width: 52, textAlign: "right", fontSize: 16, ...num, color: x.pen ? C.warn : i === 0 ? "#FDE68A" : C.white }}>
              {x.pen ? "0" : x.score}
            </strong>
          </Row>
        );
      })}
    </Sec>
  );
}

function StadioAnnunciato() {
  return (
    <>
      <Sec title="L'evento">
        <p style={{ fontSize: 13.5, color: C.slate300, margin: 0, lineHeight: 1.5 }}>
          Tre giorni di reining IRHA/FISE a Cremona Fiera: 4 classi e 2.300 € di added money.
        </p>
        <div style={{ display: "flex", gap: 18, marginTop: 12, flexWrap: "wrap" }}>
          {[["Iscrizioni dal", "1 agosto"], ["Chiusura", "5 settembre"], ["Segreteria", "segreteria@lombardiareining.it"]].map(([k, v]) => (
            <div key={k}><div style={{ fontSize: 10.5, color: C.slate500, textTransform: "uppercase", letterSpacing: 0.8 }}>{k}</div><div style={{ fontSize: 13.5, fontWeight: 700, ...num }}>{v}</div></div>
          ))}
        </div>
      </Sec>
      <Sec title="Classi">
        {CLASSI.map((c) => (
          <Row key={c.nome}>
            <div style={{ fontSize: 14, fontWeight: 700 }}>{c.nome}</div>
            <PatternChip n={c.pattern} />
            {c.added && <span style={{ marginLeft: "auto", color: C.gold, fontWeight: 700, fontSize: 13, ...num }}>Added {c.added}</span>}
          </Row>
        ))}
      </Sec>
    </>
  );
}

function StadioIscrizioni() {
  return (
    <>
      <Sec title="Iscrizioni aperte" accent={C.accent} extra={<span style={{ fontSize: 12, color: C.slate300, fontWeight: 700, ...num }}>chiudono tra 6 giorni</span>}>
        <div style={{ marginBottom: 12 }}>
          <div style={{ height: 6, background: C.panel2, borderRadius: 99, overflow: "hidden" }}>
            <div style={{ width: "83%", height: "100%", background: C.accent500, borderRadius: 99 }} />
          </div>
          <div style={{ display: "flex", justifyContent: "space-between", fontSize: 10.5, color: C.slate500, marginTop: 4, ...num }}>
            <span>1 agosto</span><span>5 settembre</span>
          </div>
        </div>
        {CLASSI.map((c) => (
          <Row key={c.nome}>
            <div>
              <div style={{ fontSize: 14, fontWeight: 700 }}>{c.nome}</div>
              {c.added && <div style={{ fontSize: 11.5, color: C.gold, ...num }}>Added {c.added}</div>}
            </div>
            <span style={{ marginLeft: "auto", fontSize: 12.5, color: C.slate400, ...num }}>{c.iscritti} binomi iscritti</span>
          </Row>
        ))}
        <button style={{ marginTop: 12, width: "100%", background: C.accent, color: C.white, border: "none", borderRadius: 8, padding: "12px 0", fontSize: 14, fontWeight: 700, cursor: "pointer" }}>
          Iscrivi la tua scuderia
        </button>
      </Sec>
    </>
  );
}

