function StadioDraw() {
  const [giorno, setGiorno] = useState("Sabato 13");
  const [q, setQ] = useState("");
  const query = q.trim().toLowerCase();
  const match = (b) => query && (b[0] + " " + b[1] + " " + b[2]).toLowerCase().includes(query);
  const nMatch = query ? Object.values(GIORNATE).flat().reduce((s, c) => s + c.binomi.filter(match).length, 0) : 0;
  return (
    <>
      {/* trova il tuo binomio */}
      <div style={{ display: "flex", gap: 8, marginBottom: 12, alignItems: "center" }}>
        <div style={{ position: "relative", flex: 1 }}>
          <svg viewBox="0 0 24 24" style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", width: 15, height: 15 }} fill="none" stroke={C.slate500} strokeWidth="2.4" strokeLinecap="round">
            <circle cx="11" cy="11" r="7" /><path d="M20 20l-4.2-4.2" />
          </svg>
          <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Trova il tuo binomio — cavallo, cavaliere o scuderia"
            style={{ width: "100%", boxSizing: "border-box", background: C.panel, border: `1px solid ${C.panel2}`, borderRadius: 10, padding: "11px 14px 11px 34px", fontSize: 13.5, color: C.white, outline: "none" }} />
        </div>
        {query && <span style={{ fontSize: 12, color: nMatch ? C.accent500 : C.warn, fontWeight: 700, ...num }}>{nMatch ? `${nMatch} trovati` : "nessuno"}</span>}
      </div>
      {/* giornate */}
      <div style={{ display: "flex", gap: 6, marginBottom: 12 }}>
        {Object.keys(GIORNATE).map((g) => (
          <button key={g} onClick={() => setGiorno(g)} style={{
            border: "none", borderRadius: 8, padding: "7px 14px", fontSize: 12.5, fontWeight: 700, cursor: "pointer",
            background: giorno === g ? C.accent : C.panel, color: C.white,
          }}>{g}</button>
        ))}
      </div>
      {/* timeline delle classi */}
      <div style={{ position: "relative", paddingLeft: 18 }}>
        <div style={{ position: "absolute", left: 5, top: 8, bottom: 8, width: 2, background: C.panel2, borderRadius: 2 }} />
        {GIORNATE[giorno].map((c) => {
          const visibili = query ? c.binomi.filter(match) : c.binomi;
          const spenta = query && visibili.length === 0 && !c.attesa;
          return (
            <div key={c.nome} style={{ position: "relative", marginBottom: 14, opacity: spenta ? 0.35 : 1 }}>
              <div style={{ position: "absolute", left: -17, top: 14, width: 8, height: 8, borderRadius: 99, background: C.accent500 }} />
              <section style={{ background: C.panel, borderRadius: 12, overflow: "hidden" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 16px", borderBottom: c.attesa ? "none" : `1px solid ${C.panel2}` }}>
                  <div style={{ fontSize: 18, fontWeight: 800, ...num }}>{c.inizio}</div>
                  <div style={{ minWidth: 0 }}>
                    <div style={{ fontSize: 14.5, fontWeight: 800 }}>{c.nome}</div>
                    <div style={{ fontSize: 11.5, color: C.slate400, ...num }}>{(c.nBinomi || c.binomi.length + c.altri)} binomi · {c.durata}</div>
                  </div>
                  <span style={{ marginLeft: "auto" }}><PatternChip n={c.pattern} /></span>
                </div>
                {c.attesa && (
                  <div style={{ padding: "10px 16px 12px", borderTop: `1px solid ${C.panel2}`, display: "flex", alignItems: "center", gap: 8 }}>
                    <span style={{ fontSize: 12, color: C.slate400 }}>Ordine di entrata: <strong style={{ color: C.slate300 }}>sorteggio sabato sera</strong> — lo pubblichiamo qui appena esce.</span>
                  </div>
                )}
                {!spenta && visibili.map((b, i) => {
                  const hit = match(b);
                  const pos = c.binomi.indexOf(b) + 1;
                  return (
                    <div key={b[0] + b[3]} style={{ display: "flex", alignItems: "baseline", gap: 10, padding: "8px 16px",
                      borderTop: i === 0 ? "none" : `1px solid ${C.panel2}`,
                      background: hit ? "rgba(22,163,74,.16)" : "transparent" }}>
                      <span style={{ width: 20, color: C.slate500, fontWeight: 700, fontSize: 12.5, ...num }}>{pos}</span>
                      <div style={{ minWidth: 0 }}>
                        <span style={{ fontSize: 13.5, fontWeight: 700 }}>{b[0]}</span>
                        <span style={{ fontSize: 12.5, color: C.slate400 }}> · {b[1]}</span>
                        <div style={{ fontSize: 11, color: C.slate500 }}>{b[2]}</div>
                      </div>
                      <span style={{ marginLeft: "auto", fontSize: 12, color: hit ? C.accent500 : C.slate500, fontWeight: hit ? 800 : 400, ...num }}>{b[3]}</span>
                    </div>
                  );
                })}
              </section>
            </div>
          );
        })}
      </div>
      <p style={{ fontSize: 11, color: C.slate500, margin: "2px 0 0 18px" }}>Orari stimati sul ritmo di 4 minuti a run — si aggiorneranno in diretta.</p>
    </>
  );
}

