const CONCLUSE_OGGI = []; // a fine giornata le classi concluse compaiono qui col ✓

function RigaOrdine({ b, hit, campoRef }) {
  const fatto = b.stato === "fatto", campo = b.stato === "campo";
  return (
    <div ref={campo ? campoRef : null} style={{
      display: "flex", alignItems: "baseline", gap: 10, padding: "8px 10px",
      borderTop: `1px solid ${C.panel2}`, borderRadius: campo ? 8 : 0,
      background: campo ? "rgba(220,38,38,.12)" : hit ? "rgba(22,163,74,.14)" : "transparent",
      opacity: fatto && !hit ? 0.62 : 1,
    }}>
      <span style={{ width: 20, color: C.slate500, fontWeight: 700, fontSize: 12.5, ...num }}>{b.pos}</span>
      <div style={{ minWidth: 0, flex: 1 }}>
        <span style={{ fontSize: 13.5, fontWeight: campo ? 800 : 700 }}>{b.c}</span>
        <span style={{ fontSize: 12.5, color: C.slate400 }}> · {b.r}</span>
        <div style={{ fontSize: 11, color: C.slate500 }}>{b.sc}{b.pen ? ` · ${b.pen}` : ""}</div>
      </div>
      {fatto && b.g && b.g.length > 1 && (
        <span style={{ display: "flex", gap: 10 }}>
          {b.g.map((s, k) => (
            <span key={k} style={{ width: 38, textAlign: "right", fontSize: 12, color: b.pen ? C.slate500 : C.slate300, ...num }}>{s}</span>
          ))}
        </span>
      )}
      {fatto && <strong style={{ width: 46, textAlign: "right", fontSize: 14, ...num, color: b.pen ? C.warn : C.white }}>{b.score}</strong>}
      {campo && (
        <span style={{ display: "inline-flex", alignItems: "center", gap: 6, color: C.live, fontSize: 12, fontWeight: 800 }}>
          <span style={{ width: 7, height: 7, borderRadius: 99, background: C.live }} /> in campo
        </span>
      )}
      {b.stato === "prossimo" && <span style={{ fontSize: 12.5, color: hit ? C.accent500 : C.slate400, fontWeight: hit ? 800 : 600, ...num }}>{b.ora}</span>}
    </div>
  );
}

// ————— ordine di giornata: le classi sono sezioni collassabili della lista —————
function OrdineGiornata({ q }) {
  const query = q.trim().toLowerCase();
  const match = (b) => query && (b.c + " " + b.r + " " + (b.sc || "")).toLowerCase().includes(query);
  const [aperte, setAperte] = useState(() => {
    const init = {};
    Object.entries(ORDINI).forEach(([nome, d]) => { init[nome] = d.stato === "corsa"; });
    return init;
  });
  const toggle = (nome) => setAperte({ ...aperte, [nome]: !aperte[nome] });

  return (
    <div style={{ position: "relative", paddingLeft: 18 }}>
      <div style={{ position: "absolute", left: 5, top: 8, bottom: 8, width: 2, background: C.panel2, borderRadius: 2 }} />
      {Object.entries(ORDINI).map(([nome, d]) => {
        const visibili = query ? d.righe.filter(match) : d.righe;
        const spenta = query && visibili.length === 0;
        const aperta = query ? visibili.length > 0 : aperte[nome];
        return (
          <div key={nome} style={{ position: "relative", marginBottom: 12, opacity: spenta ? 0.35 : 1 }}>
            <div style={{ position: "absolute", left: -17, top: 16 }}>
              {d.stato === "corsa" && <span style={{ display: "block", width: 8, height: 8, borderRadius: 99, background: C.live }} />}
              {d.stato === "conclusa" && <span style={{ color: C.accent500, fontSize: 11, fontWeight: 800, lineHeight: 1 }}>✓</span>}
              {d.stato === "prossima" && <span style={{ display: "block", width: 8, height: 8, borderRadius: 99, border: `2px solid ${C.slate500}`, boxSizing: "border-box" }} />}
            </div>
            <section style={{ background: C.panel, borderRadius: 12, overflow: "hidden" }}>
              <button onClick={() => toggle(nome)} style={{
                width: "100%", display: "flex", alignItems: "center", gap: 12, padding: "12px 16px",
                background: "none", border: "none", cursor: "pointer", color: C.white, textAlign: "left",
              }}>
                <span style={{ color: C.slate500, fontSize: 11, width: 10 }}>{aperta ? "▾" : "▸"}</span>
                <span style={{ minWidth: 0, flex: 1 }}>
                  <span style={{ display: "block", fontSize: 14.5, fontWeight: 800 }}>{nome}</span>
                  <span style={{ display: "block", fontSize: 11.5, color: C.slate400, ...num }}>{d.righe.length} binomi</span>
                </span>
                <span style={{ fontSize: 11.5, color: d.stato === "conclusa" ? C.accent500 : C.slate400, textAlign: "right", flexShrink: 0, ...num }}>{d.info}</span>
              </button>
              {aperta && !spenta && (
                <div style={{ borderTop: `1px solid ${C.panel2}` }}>
                  {visibili.map((b) => <RigaOrdine key={nome + b.pos} b={b} hit={match(b)} campoRef={null} />)}
                </div>
              )}
            </section>
          </div>
        );
      })}
      <p style={{ fontSize: 10.5, color: C.slate500, margin: "0 0 0 0", ...num }}>Orari stimati sul ritmo attuale · 4 min a run</p>
    </div>
  );
}

