// parziali dei tre giudici coerenti col totale (dato d'esempio deterministico)
const g3 = (tot) => {
  const t = parseFloat(tot.replace(",", "."));
  if (!t) return ["0", "0", "0"];
  const b = t / 3;
  const f = (x) => x.toFixed(1).replace(".", ",");
  return [f(b + 0.5), f(b), f(b - 0.5)];
};

