function ClassificheFinali() {
  const classi = Object.keys(FINALI);
  const [cl, setCl] = useState(classi[0]);
  const [liv, setLiv] = useState("L1");
  const dati = FINALI[cl];
  const livAttivo = dati.livelli.includes(liv) ? liv : dati.livelli[0];
  const righe = dati.righe.filter((x) => livAttivo === "Generale" || x.liv.includes(livAttivo));
  return (
    <Sec title="Classifiche complete" extra={
      dati.livelli.length > 1 && (
        <span style={{ display: "flex", gap: 4 }}>
          {dati.livelli.map((l) => (
            <button key={l} onClick={() => setLiv(l)} style={{
              border: "none", borderRadius: 6, padding: "4px 10px", fontSize: 11.5, fontWeight: 700, cursor: "pointer",
              background: livAttivo === l ? C.accent : C.panel2, color: C.white,
            }}>{l}</button>
          ))}
        </span>
      )
    }>
      <div style={{ display: "flex", gap: 4, marginBottom: 10, flexWrap: "wrap" }}>
        {classi.map((c) => (
          <button key={c} onClick={() => { setCl(c); setLiv("L1"); }} style={{
            border: "none", borderRadius: 99, padding: "6px 12px", fontSize: 12, fontWeight: 700, cursor: "pointer",
            background: cl === c ? C.white : C.panel2, color: cl === c ? C.ink900 : C.slate300,
          }}>{c}</button>
        ))}
      </div>
      {livAttivo === "Generale" && (
        <div style={{ fontSize: 11, color: C.warn, marginBottom: 6 }}>Vista non ufficiale — i livelli premiano separatamente</div>
      )}
      {righe.map((x, i) => {
        const podio = ["#C8902F", "#94A3B8", "#B45309"];
        const euro = x.euro && x.euro[livAttivo];
        const g = g3(x.score);
        return (
          <Row key={x.c + livAttivo}>
            <span style={{ width: 22, color: i < 3 && !x.pen ? podio[i] : C.slate500, fontWeight: 800, ...num }}>{x.pen ? "—" : i + 1}</span>
            <div style={{ minWidth: 0, flex: 1 }}>
              <div style={{ fontSize: 14, fontWeight: i === 0 && !x.pen ? 800 : 700 }}>{x.c}</div>
              <div style={{ fontSize: 11.5, color: C.slate400 }}>{x.r} · {x.sc}{livAttivo === "Generale" ? ` · ${x.liv.join(" ")}` : ""}{x.pen ? ` · ${x.pen}` : ""}</div>
            </div>
            {euro && <span style={{ fontSize: 11.5, color: C.gold, fontWeight: 700, ...num }}>{euro}</span>}
            <span style={{ display: "flex", gap: 10 }}>
              {g.map((s, k) => (
                <span key={k} style={{ width: 38, textAlign: "right", fontSize: 12, color: x.pen ? C.slate500 : C.slate300, ...num }}>{s}</span>
              ))}
            </span>
            <strong style={{ width: 46, textAlign: "right", fontSize: 16, ...num, color: x.pen ? C.warn : i === 0 ? "#FDE68A" : C.white }}>
              {x.pen ? "0" : x.score}
            </strong>
          </Row>
        );
      })}
    </Sec>
  );
}

